out = {
    "b": repo.read("src/nested/b.txt"),
    "docs_history": repo.read("docs/history.txt"),
}
# Check for related variants across repo
for pat in ["legacy_flag", "LEGACY_FLAG", "LegacyFlag", "legacyflag", "legacy-flag", "legacy_flags"]:
    hits = repo.search(pat)
    out[pat] = [{"path": h.path, "line": h.line, "text": h.text} for h in hits]
return out
